"""Exact quintic-obstruction certificate for PROB20-12.

Verifies for the K6 rank-(2,2,2) colored-perfect-matching marginal map A:
  * the predecessor's 135 degree-3 and 630 primitive degree-4 moves;
  * an explicit degree-5 A-fiber has exactly two relatively-prime monomials;
  * hence its quintic binomial is indispensable and cannot be generated by
    degree <=4 binomials / moves;
  * its S6 x S3 unsigned orbit has exactly 1080 members;
  * its kernel class is nonzero modulo the degree-3 lattice (mod 3);
  * the natural S6 x S3 action on K/L3 ~= Z/3 has character
        sign(vertex permutation) * sign(color permutation).
All finite checks use exact integer/mod-3 arithmetic.
"""
import itertools
from collections import defaultdict, Counter
import numpy as np

V=tuple(range(6)); C=tuple(range(3))
EDGES=list(itertools.combinations(V,2)); EID={e:i for i,e in enumerate(EDGES)}
def edge(e): return tuple(sorted(e))
def ix(c,e): return 15*c+EID[edge(e)]

# 90 balanced colorings / labeled perfect matchings.
ST=[]; COL=[]
for col in itertools.product(C, repeat=6):
    if all(col.count(c)==2 for c in C):
        x=[0]*45
        for c in C:
            pts=tuple(v for v in V if col[v]==c)
            x[ix(c,pts)]=1
        ST.append(x); COL.append(tuple(col))
assert len(ST)==90
A=np.array(ST,dtype=int).T

# Packed base-8 encoding. Degree <=5 sums have no carries.
CODES=[]
for x in ST:
    z=0
    for k,a in enumerate(x):
        if a: z += 1 << (3*k)
    CODES.append(z)

def relkey(pos,neg):
    a=tuple(sorted(pos)); b=tuple(sorted(neg))
    return min((a,b),(b,a))

# All degree-3 collision fibers.
D3=defaultdict(list)
for tri in itertools.combinations_with_replacement(range(90),3):
    D3[sum(CODES[s] for s in tri)].append(tri)
COLL3=[ls for ls in D3.values() if len(ls)>1]
assert len(COLL3)==135 and all(len(ls)==2 for ls in COLL3)
TR=[]
for a,b in COLL3:
    ca,cb=Counter(a),Counter(b); com=ca&cb
    aa=tuple((ca-com).elements()); bb=tuple((cb-com).elements())
    assert len(aa)==len(bb)==3 and set(aa).isdisjoint(bb)
    TR.append(relkey(aa,bb))
T=np.zeros((90,135),dtype=int)
for j,(p,n) in enumerate(TR):
    for s in p: T[s,j]=1
    for s in n: T[s,j]-=1
assert np.all(A@T==0)

# All primitive degree-4 collision fibers.
D4=defaultdict(list)
for q in itertools.combinations_with_replacement(range(90),4):
    D4[sum(CODES[s] for s in q)].append(q)
COLL4=[ls for ls in D4.values() if len(ls)>1]
assert len(COLL4)==12780 and all(len(ls)==2 for ls in COLL4)
PRIM4=[]
for a,b in COLL4:
    if not (Counter(a)&Counter(b)):
        PRIM4.append(relkey(a,b))
assert len(PRIM4)==630 and len(set(PRIM4))==630

# Explicit quintic relation found by a bounded search, then certified exactly.
POS=(13,49,50,63,77)
NEG=(21,37,51,72,76)
assert set(POS).isdisjoint(NEG)
target=sum(CODES[s] for s in POS)
assert target==sum(CODES[s] for s in NEG)
z5=np.zeros(90,dtype=int)
for s in POS: z5[s]+=1
for s in NEG: z5[s]-=1
assert np.all(A@z5==0)

# Exact meet-in-the-middle enumeration of this degree-5 A-fiber.
# Any 5-multiset has a 2+3 split. Enumerating all 2-multisets and looking up
# the complementary degree-3 code therefore finds every monomial in the fiber.
FIBER=set()
for pair in itertools.combinations_with_replacement(range(90),2):
    rem=target-CODES[pair[0]]-CODES[pair[1]]
    for tri in D3.get(rem,()):
        q=tuple(sorted(pair+tri))
        if sum(CODES[s] for s in q)==target:
            FIBER.add(q)
assert FIBER=={tuple(sorted(POS)),tuple(sorted(NEG))}

# The two monomials are relatively prime, so a two-point fiber makes the
# corresponding degree-5 binomial indispensable. In particular no move of
# degree <=4 can be applied inside this fiber.
assert not (Counter(POS)&Counter(NEG))
for p,n in TR:
    assert not (set(p).issubset(POS) or set(n).issubset(POS))
    assert not (set(p).issubset(NEG) or set(n).issubset(NEG))
for p,n in PRIM4:
    assert not (set(p).issubset(POS) or set(n).issubset(POS))
    assert not (set(p).issubset(NEG) or set(n).issubset(NEG))

# S6 x S3 orbit of the unsigned quintic relation.
idx={col:i for i,col in enumerate(COL)}
def state_map(vperm=None,cperm=None):
    if vperm is None: vperm=list(range(6))
    if cperm is None: cperm=list(range(3))
    out=[]
    for col in COL:
        new=[None]*6
        for v in V:
            new[vperm[v]]=cperm[col[v]]
        out.append(idx[tuple(new)])
    return out
GENS=[]
for a in range(5):
    p=list(range(6)); p[a],p[a+1]=p[a+1],p[a]
    GENS.append(state_map(vperm=p))
for a in range(2):
    p=list(range(3)); p[a],p[a+1]=p[a+1],p[a]
    GENS.append(state_map(cperm=p))
seed=relkey(POS,NEG)
ORB={seed}; stack=[seed]
while stack:
    p,n=stack.pop()
    for g in GENS:
        k=relkey([g[s] for s in p],[g[s] for s in n])
        if k not in ORB:
            ORB.add(k); stack.append(k)
assert len(ORB)==1080

# Exact mod-3 linear algebra.
def rref_mod(M,p=3):
    M=np.array(M,dtype=int)%p; m,n=M.shape; r=0; piv=[]
    for c in range(n):
        k=next((i for i in range(r,m) if M[i,c]),None)
        if k is None: continue
        M[[r,k]]=M[[k,r]]
        M[r]=(M[r]*pow(int(M[r,c]),-1,p))%p
        for i in range(m):
            if i!=r and M[i,c]: M[i]=(M[i]-M[i,c]*M[r])%p
        piv.append(c); r+=1
        if r==m: break
    return M,piv
def rank_mod(M,p=3): return len(rref_mod(M,p)[1])
def nullspace_mod(M,p=3):
    R,piv=rref_mod(M,p); n=R.shape[1]
    free=[j for j in range(n) if j not in piv]; out=[]
    for f in free:
        x=np.zeros(n,dtype=int); x[f]=1
        for i,pv in enumerate(piv): x[pv]=(-R[i,f])%p
        out.append(x)
    return np.array(out,dtype=int).T

assert rank_mod(T,3)==51
assert rank_mod(np.column_stack([T,z5]),3)==52  # nonzero cubic-lattice residue

# Recover a quotient character lambda: lambda annihilates all cubic moves and
# is normalized by lambda(Q)=1 on the predecessor's cube generator.
Q=np.zeros(90,dtype=int)
for s in (8,12,31,37): Q[s]+=1
for s in (7,13,32,36): Q[s]-=1
N=nullspace_mod(T.T,3)
lam=None
for j in range(N.shape[1]):
    a=int(N[:,j]@Q)%3
    if a:
        lam=(N[:,j]*pow(a,-1,3))%3; break
assert lam is not None
assert np.all(lam@T%3==0) and int(lam@Q)%3==1
assert int(lam@z5)%3==2

# Quotient symmetry character. It suffices computationally to check adjacent
# transpositions; all return -1=2 mod 3.
def transform(vec,g):
    out=np.zeros_like(vec)
    for s,t in enumerate(g): out[t]=vec[s]
    return out
classes=[]
for g in GENS:
    classes.append(int(lam@transform(Q,g))%3)
assert classes==[2]*7

print('states',len(ST))
print('degree3_moves',len(TR))
print('primitive_degree4_moves',len(PRIM4))
print('quintic_positive',POS)
print('quintic_negative',NEG)
print('quintic_fiber_size',len(FIBER))
print('quintic_orbit_size',len(ORB))
print('quintic_mod_cubic_class',int(lam@z5)%3)
print('symmetry_generator_classes',classes)
print('ALL EXACT CHECKS PASSED')
